#[derive(Clone,Copy)] struct Node{key:i64,left:i32,right:i32,npl:i32}
fn merge_nodes(a:&mut[Node;14],x:i32,y:i32)->i32{if x<0{return y}if y<0{return x}let(mut x,mut y)=(x,y);if a[x as usize].key>a[y as usize].key{std::mem::swap(&mut x,&mut y)}let rr=a[x as usize].right;a[x as usize].right=merge_nodes(a,rr,y);let l=a[x as usize].left;if l<0{a[x as usize].left=a[x as usize].right;a[x as usize].right= -1}else{let r=a[x as usize].right;if a[l as usize].npl<a[r as usize].npl{let t=a[x as usize].left;a[x as usize].left=a[x as usize].right;a[x as usize].right=t}let r=a[x as usize].right;a[x as usize].npl=a[r as usize].npl+1}x}
#[no_mangle]pub extern "C" fn leftist_heap(v:*const i64,n:usize)->f64{if n<1||n>43||v.is_null(){return -1e300}let s=unsafe{std::slice::from_raw_parts(v,n)};let m=s[0];if m<0||m>14||n!=1+3*m as usize{return -1e300}let mut a=[Node{key:0,left:-1,right:-1,npl:0};14];let mut roots=[-1i32;2];let(mut used,mut ex)=(0usize,0);let mut result=0i64;for i in 0..m as usize{let(k,h,z)=(s[1+3*i],s[2+3*i],s[3+3*i]);if !(0..=3).contains(&k){return -1e300}if k==0{if !(0..=1).contains(&h)||!(0..=9).contains(&z){return -1e300}a[used]=Node{key:z,left:-1,right:-1,npl:0};let hh=h as usize;roots[hh]=merge_nodes(&mut a,used as i32,roots[hh]);used+=1}else if k==1{if !(0..=1).contains(&h)||z!=0{return -1e300}ex+=1;if ex>10{return -1e300}let hh=h as usize;let r=roots[hh];let mut got=-1;if r>=0{got=a[r as usize].key;let l=a[r as usize].left;let rr=a[r as usize].right;roots[hh]=merge_nodes(&mut a,l,rr)}result=result*13+got+2}else if k==2{if h!=0||z!=0{return -1e300}roots[0]=merge_nodes(&mut a,roots[0],roots[1]);roots[1]= -1}else{if !(0..=1).contains(&h)||z!=0{return -1e300}roots[h as usize]= -1}}result as f64}
